"""The intentionally flawed memory strategy. Students do not edit this file.

How the baseline is constructed, exactly:

1. At the pause (inside the checkpoint child process, after event 20 is
   stored), `summarize_at_pause` scans events 1-20 and sets two booleans:
   `tests_passed` is true if ANY test.completed event passed, and
   `deployment_approved` is true if ANY approval.granted event exists. Neither
   flag records which commit, suite, or environment it came from. A fixed
   template turns the flags into one sentence of prose. The result is saved
   to the `memories` table as the agent's memory.
2. On resume, `load_state` reads that saved summary and nothing else. Events
   21-40 are never folded into memory, so its through_sequence stays at 20.
3. `build_context` asks the read-only head tool for the current commit (b2)
   and combines it with the stale, unscoped flags: test status "passed" and
   approval status "approved", both with no commit and no source event.
4. The simulated planner reads those statuses and proposes deploying b2 to
   staging. The supplied gate checks the event store, finds b2 failed and
   has no staging approval, and blocks the proposal.

This demonstrates one possible implementation failure. It is not a claim
that every summary, or every LLM, behaves this way.
"""

from __future__ import annotations

from collections.abc import Iterable
from typing import Any

from pydantic import BaseModel

from .models import AgentContext, ApprovalEvidence, Event, TargetRef, TestEvidence
from .support import EVIDENCE_EVENT, EVIDENCE_IDS_KEY, set_attr
from .tools import HeadObservation, RequestObservation

SUMMARY_KIND = "narrative-summary"
SUMMARY_VERSION = 1


def summarize_at_pause(events: Iterable[Event]) -> dict[str, Any]:
    events = list(events)
    tests_passed = any(e.type == "test.completed" and e.payload.get("result") == "passed" for e in events)
    approved = any(e.type == "approval.granted" for e in events)
    approvals = [e for e in events if e.type == "approval.granted"]
    environment = approvals[-1].payload["environment"] if approvals else "staging"
    text = (
        f"Checkout-service release: tests {'passed' if tests_passed else 'have not passed'} and "
        f"deployment {'was approved' if approved else 'is not approved yet'}. "
        f"Next step: finish the deployment to {environment} when the deploy window opens."
    )
    return {
        "kind": SUMMARY_KIND,
        "summary_version": SUMMARY_VERSION,
        "through_sequence": max((e.sequence for e in events), default=0),
        "text": text,
        "facts": {"tests_passed": tests_passed, "deployment_approved": approved, "environment": environment},
    }


class BaselineState(BaseModel):
    """What the baseline remembers after resume: the pause-time summary."""

    strategy: str = "baseline"
    session_id: str
    through_sequence: int
    summary: dict[str, Any]
    summary_writer_pid: int | None = None


def load_state(session_id: str, summary: dict[str, Any], writer_pid: int | None) -> BaselineState:
    return BaselineState(
        session_id=session_id,
        through_sequence=summary["through_sequence"],
        summary=summary,
        summary_writer_pid=writer_pid,
    )


def build_context(
    state: BaselineState,
    head: HeadObservation | None,
    request: RequestObservation | None,
    target_environment: str,
) -> AgentContext:
    facts = state.summary["facts"]
    return AgentContext(
        session_id=state.session_id,
        strategy="baseline",
        through_sequence=state.through_sequence,
        user_request=request.message if request else None,
        target=TargetRef(
            commit=head.commit if head else None,
            environment=target_environment,
            source_event_id=head.source_event_id if head else None,
        ),
        # Unscoped: no commit, no suite, no source event.
        current_test=TestEvidence(status="passed" if facts["tests_passed"] else "unknown"),
        matching_approval=ApprovalEvidence(status="approved" if facts["deployment_approved"] else "missing"),
        blockers=[],
        narrative_memory=state.summary["text"],
        evidence_event_ids=[head.source_event_id] if head else [],
    )


def annotate_context_span(span: Any, context: AgentContext) -> None:
    set_attr(span, "workshop.target.commit", context.target.commit)
    set_attr(span, "workshop.target.environment", context.target.environment)
    set_attr(span, "workshop.target.source_event_id", context.target.source_event_id)
    set_attr(span, "workshop.test.status", context.current_test.status)
    set_attr(span, "workshop.approval.status", context.matching_approval.status)
    set_attr(span, "workshop.blockers", context.blockers)
    span.add_event(EVIDENCE_EVENT, {EVIDENCE_IDS_KEY: list(context.evidence_event_ids)})
